import{_ as i,P as s,d as o,e as r,x as t,q as n}from"./chunks/framework.BRr8VP3a.js";const g=JSON.parse('{"title":"Part 2 Boundaries and Methods","description":"","frontmatter":{"title":"Part 2 Boundaries and Methods","xkChars":4,"xkWords":6553,"xkLessons":{"2.1.1":{"title":"Domain evidence keeps its own standing","lead":"A framework-specific eligibility rule must not erase a conclusion supported by another appropriate method.","explanation":["The section separates a real object or domain finding from eligibility for a particular formal instance in this framework. A document can establish that an organization was registered; observations can establish what a service did. These facts do not wait for a G1 grouping-gain test.","G1 instead asks whether a declared grouping improves a specified explanatory or forecasting task relative to the matched null model and other conditions. An unsupported grouping-gain claim therefore leaves the independently grounded object facts intact.","The same discipline applies to learning, injury, or a historical effect. Existing research retains the support its actual design provides. It must not be silently upgraded into a pre-registered framework test, but neither should it be dismissed because it lacks the framework’s identifiers."],"distinctions":[{"leftTitle":"Object fact","leftText":"Supported by appropriate documentary or observational evidence.","rightTitle":"Grouping gain","rightText":"A task-relative comparison with its own instance conditions."}],"teachingExamples":[{"title":"A registered team and a predictive grouping","text":"Suppose reliable records show a team exists. Grouping its members together fails to improve a particular forecast over a simpler baseline. The team’s documented existence remains supported; the forecast grouping gain does not.","assumptions":"Hypothetical example; the baseline and target are assumed to be appropriately specified.","boundary":"It does not establish any real team or measured gain."}],"boundaries":["Do not retroactively label existing studies pre-registered G-instances.","A source’s existence is not enough: its actual method must support the particular claim."],"questionAnswers":[{"question":"Does missing G1 support make the organization nonexistent?","answer":"No. It limits the grouping-gain claim. Object facts and each domain conclusion retain their independent evidential bases.","basis":"Theory v2, §2.1.1, with the distinctions explained above."}],"caseLinks":[{"title":"London taxi trainees: distinct learning outcomes","href":"/en/cases/london-taxi-learning"}],"sourceRefs":[{"section":"2.1.1","startLine":251,"endLine":258}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-1-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.1.1; English reading edition, lines 251–258","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.4.2":{"title":"Average effects do not automatically join into one chain","lead":"The units responding to the first link may be different from those responding to the second.","explanation":["A causal chain needs more than separately positive averages. The question concerns the joint response of the same cases under compatible conditions. Timing, common support, capacity, and the final outcome must also match the proposed composition.","The source’s two-type construction makes the missing correspondence visible. One type changes its mediator in response to treatment but has no outcome response to that mediator. The other type has an outcome response but no treatment-induced mediator change. Each average link is positive, while the whole-chain effect is zero.","This counterexample does not withdraw a total effect independently identified by a valid design. A total effect, a specific mediator, and a composed chain are different estimands; knowing one does not require pretending to know all the others."],"distinctions":[{"leftTitle":"Separate link averages","leftText":"May describe effects across different responding units.","rightTitle":"Whole-chain effect","rightText":"Requires compatible joint response and the endpoint of the same chain."}],"teachingExamples":[{"title":"Two equally weighted types","text":"For s∈{0,1}, set m(a)=a(1−s) and y(a,m)=sm. Each link’s average effect is 1/2, but y(a,m(a)) is always zero. Multiplying the averages gives a false 1/4.","assumptions":"The two types have equal weight and exactly the stipulated response functions.","boundary":"A formal counterexample, not a real population estimate."}],"boundaries":["The counterexample rules out unconditional multiplication; it does not show all causal composition is impossible."],"questionAnswers":[{"question":"Must a well-identified total effect be rejected if one mediator remains unknown?","answer":"No. Preserve the supported total effect and leave the unresolved mechanism separate.","basis":"Theory v2, §2.4.2, with the distinctions explained above."}],"caseLinks":[{"title":"Two effective links can fail as a whole","href":"/en/concepts/chain"}],"sourceRefs":[{"section":"2.4.2","startLine":333,"endLine":340}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-4-2","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.4.2; English reading edition, lines 333–340","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.4.3":{"title":"A valid status and its consequences need different evidence","lead":"Constitutive standing is established under applicable rules; causal effects concern what happens through it.","explanation":["Some relations constitute an office, right, membership, authorization, or promise under the rules of the relevant practice. Their standing is not inferred simply by observing that they produced an effect. A valid right may be obstructed in practice; actual influence can exist without valid authority.","Keep four inquiries visible: whether constitutive conditions hold, how participants understand the arrangement, whether it is implemented, and whether it is normatively justified. Documentary interpretation and causal inquiry may both matter, but answer different questions.","This prevents two opposite errors. Lack of an observed consequence does not automatically cancel an established right. A successful intervention does not retroactively supply a missing mandate or prove that a rule is just."],"distinctions":[{"leftTitle":"Constitutive relation","leftText":"The applicable rules establish a specified standing.","rightTitle":"Causal relation","rightText":"A supported channel explains an actual effect."}],"teachingExamples":[{"title":"An approved entitlement and a delayed payment","text":"Assume a valid decision grants a benefit, but payment has not arrived. The entitlement may already exist; delivery remains incomplete. Whether the arrangement is fair requires a further argument.","assumptions":"The validity of the decision is independently established; no real legal case is asserted.","boundary":"The example does not determine any jurisdiction’s rules or authorize collection."}],"boundaries":["The framework does not invent the constitutive rules of a domain.","Legal validity and normative justification remain distinct."],"questionAnswers":[{"question":"If an unauthorized actor successfully solves a problem, has the success created authorization?","answer":"No. Effectiveness does not supply the applicable constitutive conditions for authority.","basis":"Theory v2, §2.4.3, with the distinctions explained above."}],"caseLinks":[{"title":"Democratic authorization: the scope of an office","href":"/en/cases/democratic-authorization"}],"sourceRefs":[{"section":"2.4.3","startLine":341,"endLine":348}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-4-3","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.4.3; English reading edition, lines 341–348","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.14":{"title":"Freeze a test without monopolizing the question","lead":"Preserve the original question and result while allowing a justified new question to be opened.","explanation":["Freezing protects an inquiry against moving its target after the outcome is known. It does not give the original question-setter permanent ownership of the goal, population, losses, or constraints. Affected and excluded positions can identify omissions and challenge the framing.","A reopening request should identify what changes and why. Its handling and reasons remain on record even if it is rejected. A new inquiry preserves the old question, evidence, and result rather than replacing a failure with a newly convenient success.","This matters especially when an apparent constraint is itself a prior decision. Asking who controls a shortage can open a relevant policy question. It cannot change what the original resource-limited test actually found.","State whether the new question replaces, runs parallel to, or refines the old one, and which existing evidence still applies. The analyst may answer both side by side. Actual changes to an institution’s indicators, eligibility, agenda, or resource allocation belong to the procedure with the corresponding authority; an analytical reframing does not itself change those rules."],"distinctions":[{"leftTitle":"Preserve the test","leftText":"Keep its original target, conditions, and outcome.","rightTitle":"Reopen the question","rightText":"State a new framing and preserve the history of the change."}],"teachingExamples":[{"title":"A service target omitted waiting time","text":"Suppose a frozen review measures completed transactions. Users then identify an omitted waiting burden. Keep the transaction result, record the challenge, and assess a new waiting-time question with suitable evidence.","assumptions":"Hypothetical review; transaction counts are assumed accurate.","boundary":"The omission does not automatically prove the original numerical result false."}],"boundaries":["Reopening is not permission for retrospective success claims.","An affected person need not master the framework’s terminology to challenge a question."],"questionAnswers":[{"question":"Is a disappointing outcome alone a reason to redefine success?","answer":"No. A new question needs an explicit reason and its own record; the old outcome is retained.","basis":"Theory v2, §2.14, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"2.14","startLine":453,"endLine":472}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-14","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.14; English reading edition, lines 453–472","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-02.md","filePath":"en/theory/part-02.md"}'),c={name:"en/theory/part-02.md"};function l(d,e,h,p,u,m){const a=s("SectionLesson");return o(),r("div",null,[e[0]||(e[0]=t('<div class="theory-source"><p><a id="part_2"></a></p><h1 id="part-title-2" tabindex="-1">Part 2 Boundaries and Methods <a class="header-anchor" href="#part-title-2" aria-label="Permalink to &quot;Part 2 Boundaries and Methods {#part-title-2}&quot;">​</a></h1><p>The ultimate object domain of this framework is the broadly conceived empirical structural world. Natural processes, technical systems, ecological processes, human actions, organizations, and institutions can all enter structural explanation if they can leave comparable materials and allow researchers to declare candidate objects, states, relations or transitions, interfaces, time windows, scale profiles, and identity criteria. The human structured world is not a synonym for the world as a whole. It is a specialized domain within that world, requiring additional human-domain clauses, normative commitments, and authorization procedures. Purely metaphysical assertions, objects for which no empirical fields can be supplied, and “systems” established solely through naming or narrative coherence do not enter empirical judgment. They may be discussed, but they must not borrow this framework&#39;s levels of empirical conclusions.</p><p>The current scope of application must still be declared separately each time: the object, SP/T/K, region or environment, data window, extrapolation unit, and exclusions. Belonging to the broadly conceived empirical structural world means only that a contract<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> can in principle be established. It does not imply that any conclusion can be directly generalized across windows, objects, or domains.</p><p>This choice of scope also sets the framework&#39;s limits. The framework seeks to explain how objects form identifiable structures, how they operate, how they change or undergo dissolution under the effects of conditions, and how descriptions at different scales can be converted. It does not presuppose a unified purpose for the world, project human intentions onto nonhuman processes, or infer “how one should choose” directly from “what is.” Real-world choices are taken up by the normative layer and operational procedures separately.</p><h2 id="section-2-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.1</span><span class="xk-num__gap"></span></span>Two-Stage Object Admission <a class="header-anchor" href="#section-2-1" aria-label="Permalink to &quot;2.1 Two-Stage Object Admission {#section-2-1}&quot;">​</a></h2><p>Structural modeling begins with candidate objects, without presupposing that the grouping has already received support for a grouping gain, and without letting a declaration substitute for grounds for object facts. When applying for formal support for root instances within this framework, object admission has two stages whose order must not be reversed. This procedure governs strong empirical claims made under G and the C and CM claims that depend on it. It is not a universal truth check for all domain knowledge, historical records, or everyday understanding.</p><p>The first stage is the declaration of a candidate object. The analyst registers S*=&lt;B,X,R,I,T,SP,K&gt; under a D0 contract: boundary B, state variables X, relations or transition constraints R, interface I, time window T, scale profile SP, and identity criterion K. The asterisk indicates that the object remains an analytical candidate. Complete fields establish only that the question has been stated clearly. They do not establish that the grouping has relatively independent empirical standing in the world. When fields are incomplete, only exploratory questions may be proposed.</p><p>The second stage is testing of root instances. When the analyst claims grouping gains, effects of specified channels, historical conditional increments, or scale closure under G1–G4, and applies for eligibility for formal support within this framework, a corresponding G-instance must be established. Before viewing the results, an immutable contract version and an auditable timestamp must be used to freeze the null model N0, a single subtype, one success criterion selected from that subtype&#39;s admissible list, controls, models, samples and extrapolation units, evaluation metrics, positive thresholds, decision rules, rules for null conclusions, falsification conditions, and suspension conditions. Instances with multiple targets or models must also freeze the primary target or aggregation, model selection or ensembling, and rules for multiple comparisons. This support eligibility belongs to the specific instance that passes the test, not to the D0 declaration or the abstract templates G1–G4.</p><p>Support eligibility requires that exploratory work be kept separate from confirmatory work, positive results from null conclusions, and completed freezing from post hoc deviations. Only confirmatory or replication instances completed under a contract frozen before the evidence can provide positive support. Falsification instances support only the pre-registered falsification or null-model judgment. Exploratory work, drafts, post-evidence deviations, or undisclosed deviations can only generate candidates, register deviations, or remain unresolved. They must not use formal-instance eligibility to support C branches that require that eligibility. Failure to pass the positive-support check does not automatically support N0 either. Unless equivalence or sufficiency, statistical power or sensitivity, and tolerance have been pre-registered and their requirements met, the conclusion can only be “not positively supported” or “unresolved.” Thus, “the candidate object has been registered,” “positive G is not supported,” “the null model is supported,” and “the instance receives limited positive support” must remain distinct states.</p><p>This two-stage structure prevents two opposite errors: treating the analyst&#39;s naming, clustering, or boundary choice as meaning that a grouping gain or object facts have already been supported; and piecing scattered materials together after the fact into an unfalsifiable “system” before the object has even been declared.</p><h3 id="section-2-1-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.1.1</span><span class="xk-num__gap"></span></span>Domain Evidence and Formal Instance Eligibility <a class="header-anchor" href="#section-2-1-1" aria-label="Permalink to &quot;2.1.1 Domain Evidence and Formal Instance Eligibility {#section-2-1-1}&quot;">​</a></h3><p>Existing studies, archives, oral accounts, archaeological materials, and locatable source texts can support the relevant descriptions, explanations, or limited causal conclusions according to their actual research designs. When these materials are used, whether they are pre-registered confirmatory work, post hoc findings, exploratory work, historical reconstruction, or other research should be preserved accurately. A pre-result contract must not be fabricated for them. These materials cannot thereby acquire G-instance support automatically, nor do they lose their originally supported content merely because they have not yet been converted into G-instance form.</p><p>If an existing finding is to be used in a new formal root instance, it may first serve as a source of questions and models, then be tested using independent materials, a later window, or an appropriate replication design. Data used for exploratory work must be separated from data used for confirmatory work, and model selection from final evaluation. Where no feasible new test is available, retain the domain conclusion and the relation awaiting testing; do not fabricate confirmation.</p><p>Formal proofs hold under their axioms, semantics, and rules of derivation. Textual interpretation is open to criticism on the basis of editions, contexts, and argumentative materials. Normative claims disclose their value premises and reasons. They can contribute to analysis, but must not masquerade as one another&#39;s empirical mechanisms, factual truth, or real-world authorization.</p></div>',1)),n(a,{section:"2.1.1"}),e[1]||(e[1]=t('<div class="theory-source"><h3 id="section-2-1-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.1.2</span><span class="xk-num__gap"></span></span>Connecting Formal Conclusions and Empirical Instances <a class="header-anchor" href="#section-2-1-2" aria-label="Permalink to &quot;2.1.2 Connecting Formal Conclusions and Empirical Instances {#section-2-1-2}&quot;">​</a></h3><p>Formal propositions first specify the state domain, mapping, target, admissible operations, and logical premises; proof then establishes their conclusions. Exhaustive enumeration of a complete finite domain can test every case within that domain. Numerical computation must also specify precision, boundary determination, and implementation error. Proof, exhaustive enumeration, and numerical checks can cross-check one another, but together they do not generate real-world samples, and more computations do not increase independent empirical support.</p><p>Applying a formal conclusion to a real-world object requires a separate account of how real-world quantities correspond to model variables, which premises are already supported by materials, whether the errors and applicable ranges are acceptable, and what counterexamples would invalidate the mapping. “The proposition holds in the given model” and “whether the real-world object satisfies the model remains undetermined” can both be acknowledged. A mathematical counterexample is already sufficient to refute the unconditional inference it addresses. The absence of a completed real-world experiment does not erase this formal answer. Conversely, formal feasibility, the existence of an algorithm, computability within budget, timely availability of data, correct execution in practice, and authority to adopt are six judgments, each requiring its own basis.</p><h2 id="section-2-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.2</span><span class="xk-num__gap"></span></span>Proposition Roles and the Burden of Argument <a class="header-anchor" href="#section-2-2" aria-label="Permalink to &quot;2.2 Proposition Roles and the Burden of Argument {#section-2-2}&quot;">​</a></h2><p>Formal judgments first distinguish six commonly used roles: D, G, E, H, N, and O. Conditional formal propositions provable within a model are designated separately as F. If a single natural-language sentence mixes definitional, empirical, formal, methodological, or normative commitments, it must be separated into its components, with the basis for each stated separately. The identifiers organize the burden of argument; they do not mean that all kinds have the same truth conditions.</p><p>D, definitions. These specify how terms are used within the framework; they are not empirical facts about the world. Definitions can make judgments consistent, but cannot by themselves establish the existence of objects, mechanisms, or historical effects.</p><p>G, empirical question families. G1–G4 organize empirical questions about grouping gains, specified channels, historical conditional increments, and representational closure, respectively. Specific instances must take the form of factual assertions with an object, target, conditions, comparison, and mode of failure—for example, whether a specified difference exceeds a threshold. Whether a fact is true and whether evidence is sufficient to support it are different questions. Pre-registration, review, and release rules govern eligibility for formal support; they do not define whether an effect exists in the world.</p><p>E, epistemic constraints. These specify the valid scope of observation, measurement, inference, and cross-scale transfer, requiring that blind spots, competing explanations, and residuals be retained.</p><p>H, human-domain clauses. H1, H4, and H5 are empirical hypotheses requiring case-specific evidence. H2 is an operational classification rule. H3 is a classification rule for institutional write-back. H6 is a normative boundary. H marks adaptation to the human domain; it is not a logical type mutually exclusive with definition, empirical content, or normative content. H clauses must not be treated as an unclassified set of “axioms of human nature,” nor written back as universal roots for the nonhuman world.</p><p>N, normative commitments. These explicitly declare what the framework chooses to protect and constrain. They must not be disguised as factual propositions that empirical data could prove.</p><p>O, operational procedures. These specify the freezing of descriptions, evidence audits, normative registration, authorization, comparison of options, constrained execution, review, stopping, withdrawal, and remedy.</p><p>F, conditional formal propositions. Conclusions are established by proof under explicit state domains, mappings, targets, operation sets, and mathematical assumptions. Formal counterexamples can refute universal inferences that exceed those conditions. Whether real-world objects satisfy the premises still requires independent evidence. See §4.18 for F1–F5 and §4.19 for task families and dynamic refinement.</p><p>C is not an eighth kind of fact. It combines contracts that delimit the use of outcomes with mechanism conditions; C12 provides a bridge to normative procedures. Common method constraints govern the use of representations, evidence, and inference. They do not serve as additional laws of the world.</p><p>Descriptive conclusions cannot generate normative conclusions on their own, nor can explanation or diagnosis<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> generate authority to act on their own. The minimal bridge to real-world action is:</p><p>A descriptive or explanatory conclusion + explicit normative premises + current evidence + lawful authorization + an action ceiling + conditions for stopping or withdrawal</p><p>If any element of this bridge to real-world action is missing, real-world action should stop. The associated action requirements should remain at the level of description, candidate explanations, obtaining further evidence, non-action, or proposing a reversible probe, rather than bypassing authorization through theoretical language.</p><h2 id="section-2-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.3</span><span class="xk-num__gap"></span></span>Four Kinds of Dependency Must Be Kept Separate <a class="header-anchor" href="#section-2-3" aria-label="Permalink to &quot;2.3 Four Kinds of Dependency Must Be Kept Separate {#section-2-3}&quot;">​</a></h2><p>Relations between propositions use four different contracts. They must not be merged into an ambiguously defined “dependency.”</p><div class="xk-table"><table><thead><tr><th>Kind of Dependency</th><th>Meaning</th><th>May It Enter the Inferential Acyclic Graph?</th></tr></thead><tbody><tr><td><code>inferential_requires</code></td><td>A hard inferential premise without which the conclusion cannot be obtained</td><td>Yes</td></tr><tr><td><code>protocol_requires</code></td><td>Method checks concerning evidence, causation, analogy, sources, or domain classification</td><td>No</td></tr><tr><td><code>specializes</code></td><td>Restricts a universal proposition to a particular domain, object, or subtype</td><td>No</td></tr><tr><td><code>applies_to</code></td><td>Specifies which objects, propositions, or actions a norm or procedure applies to</td><td>No</td></tr></tbody></table></div><p>Method checks determine whether a judgment may be released, but do not thereby become additional empirical causes. Domain specialization narrows the scope of application, but does not turn classification rules into factual evidence. Normative applicability constrains action, but does not in turn prove a description true. Only hard inferential premises enter the acyclic graph of roots and inferred conclusions.</p><h2 id="section-2-3-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.3.1</span><span class="xk-num__gap"></span></span>Layered Responsibilities of the Common Method Kernel <a class="header-anchor" href="#section-2-3-1" aria-label="Permalink to &quot;2.3.1 Layered Responsibilities of the Common Method Kernel {#section-2-3-1}&quot;">​</a></h2><p>This framework and <em>World Model</em> may share methodological responsibilities, while each text retains its own objects, arguments, and mode of operation. Neither serves as an authoritative source or double empirical evidence for the other. Interoperation requires checking definitions, method constraints, formal propositions, empirical questions, outcome contracts, and governance requirements one by one. A shared name cannot substitute for a correspondence.</p><div class="xk-table"><table><thead><tr><th>Layer</th><th>Question Answered</th><th>Limits of Its Force</th></tr></thead><tbody><tr><td>Definitions</td><td>What objects and terms refer to</td><td>Specify decidable semantics; do not establish that something holds in reality</td></tr><tr><td>Common method constraints</td><td>How representations, the status of materials, and inference are governed</td><td>Constrain recording and use; are not laws of the world</td></tr><tr><td>Conditional formal propositions F</td><td>What necessarily follows under explicit mathematical premises</td><td>Established by proof; real-world mappings require separate verification</td></tr><tr><td>Empirical question families G</td><td>Whether a specific empirical relation holds</td><td>Instances specify the object, comparison, mode of failure, and evidence</td></tr><tr><td>Outcome and mechanism contracts C</td><td>What the existing basis permits to be registered and used</td><td>Valid only within their dependencies, additional conditions, and applicable windows</td></tr><tr><td>Governance invariants</td><td>How to release, evaluate, suspend, and act</td><td>Limit power; do not serve as empirical causes</td></tr></tbody></table></div><p>Identifiers such as D, G, and C provide stable references. The common kernel&#39;s Chinese identifiers serve only to align texts. They cannot replace the complete contracts in the body, nor can they obtain double support merely because another text uses the same name.</p><h2 id="section-2-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.4</span><span class="xk-num__gap"></span></span>Causal Protocol<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup> <a class="header-anchor" href="#section-2-4" aria-label="Permalink to &quot;2.4 Causal Protocol[^tn-protocol-02] {#section-2-4}&quot;">​</a></h2><p>A causal claim first registers the specific version of the treatment or cause, the outcome, the object and population, the time window, the scale, and the effect being asked about. It then explains why the comparison can identify that effect. Common inputs, selection, attrition, changes in measurement, reverse causation, and interference between units must all be addressed where relevant. A claim about a specified structural channel or a complete mediation mechanism must also provide the mechanism chain, temporal sequence, and discriminating evidence at that level: whether blocking, replacement, or natural variation meeting identification conditions changes outcomes as expected; whether alternative channels can explain the difference; whether cross-layer conclusions have a D3/E5 bridge; and what observations would make the mechanism claim fail.</p><p>Temporal sequence, correlation, and a coherent story cannot by themselves identify causation. A design may identify the total effect for a bounded population and window under explicit assumptions while still leaving the mediator undetermined. In that case, it should report “limited identification of the effect; the specific mechanism is unresolved.” Unsupported structural effects must not be filled in. Conversely, the separate existence of several local links does not automatically establish that the chain is connected as a whole in this case or that the net effect holds. Opposing paths may cancel one another out, and a total effect near zero does not establish that all mechanisms are absent. Causal strength, mechanism resolution, and the scope of extrapolation are evaluated separately.</p><h3 id="section-2-4-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.4.1</span><span class="xk-num__gap"></span></span>The Estimand and Mechanism Responsibilities <a class="header-anchor" href="#section-2-4-1" aria-label="Permalink to &quot;2.4.1 The Estimand and Mechanism Responsibilities {#section-2-4-1}&quot;">​</a></h3><p>Offering someone an opportunity, that person actually receiving an intervention, and expansion of an entire institution are different treatments. A population average effect, the local average treatment effect for a particular kind of compliers, and each individual&#39;s outcome are also different estimands. When an identification assumption is impaired, downgrade only the conclusions that depend on it. For example, an interpretation based on a particular instrumental variable may no longer be reliable without automatically invalidating the effect of credible random assignment on “receiving an opportunity.”</p><p>More variables do not make observational control more reliable by default. Controlling for a mediator may change the total effect being asked about; controlling for a variable jointly determined by different causes may introduce bias. A larger sample cannot compensate for explanations that cannot be distinguished, either. When point identification is unavailable, supported bounds, sets of possible directions, exclusions based on necessary conditions, or specific process knowledge may be retained, with a clear statement of what these conclusions have not answered.</p><p>“Offering an opportunity” and “actually accepting, remaining, or exiting” are different treatments. The text of an agreement, verification, execution, and everyday use are also different outcomes. An announcement, public understanding, arrival, action at a border crossing, and full clearance must each be evidenced separately along the event chain. Neither a total effect nor the existence of an agreement can fill these gaps in mediation and distribution.</p><h3 id="section-2-4-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.4.2</span><span class="xk-num__gap"></span></span>Local Effects, Joint Responses, and the Chain as a Whole <a class="header-anchor" href="#section-2-4-2" aria-label="Permalink to &quot;2.4.2 Local Effects, Joint Responses, and the Chain as a Whole {#section-2-4-2}&quot;">​</a></h3><p>When local channels are combined, the correspondence between an earlier output and a later input, the identity of the same case and its temporal sequence, the common scope of support, joint responses, and terminal outcomes should be retained. Even when two studies concern the same population, their two average effects generally cannot be multiplied directly: the people whose mediator changes may be precisely those whose outcome would not respond to that mediator. Accurate averages on both sides do not guarantee that the common conditions needed for the sequence have been retained.</p><p>A finite counterexample is a population composed of two equally weighted types, with type denoted by s∈{0,1}, binary treatment by a, and mediator by m. Let m(a)=a(1−s), with outcome y(a,m)=sm. The average effect of treatment on the mediator and the average effect of directly setting the mediator on the outcome are both 1/2. Yet in each type, the effect of treatment on the final outcome is 0, and the effect of the chain as a whole is 0. Multiplying the two averages gives 1/4, which is not the effect of the chain as a whole. This is a counterexample under given functions. It neither estimates a real-world effect nor denies a total effect independently identified by a qualified design.</p><p>“Complete” in a claim about the chain as a whole is relative only to the declared outcome, window, and dependency route. If the purpose is to identify a particular total effect with a specified scope, there is no requirement to exhaust all microscopic processes first. If the purpose changes to manipulating a mediator, transferring across domains, or allocating responsibility, supply the connections on which that purpose actually depends. Shared resources, offsetting paths, and feedback can change the result of the connection. Separate evidence for each node cannot substitute for a joint test in the same case.</p></div>',1)),n(a,{section:"2.4.2"}),e[2]||(e[2]=t('<div class="theory-source"><h3 id="section-2-4-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.4.3</span><span class="xk-num__gap"></span></span>Constitutive Relations and Causal Relations <a class="header-anchor" href="#section-2-4-3" aria-label="Permalink to &quot;2.4.3 Constitutive Relations and Causal Relations {#section-2-4-3}&quot;">​</a></h3><p>Some relations specify what a thing counts as under a given set of rules: whether an expression becomes a commitment, whether a document becomes a valid authorization, whether a person holds membership or eligibility to apply. Constitutive relations of this kind answer whether a standing holds. Their grounds are the source of the rule, the party entitled to perform the act, the required form, and the argument that the rule applies to the present case; they are not established by estimating effects. Causal questions ask what actually happened after the standing came to hold: whether rights were honored, whether commitments were fulfilled, whether eligibility changed opportunities and behavior.</p><p>The two kinds of question are evidenced separately, and neither can pay in place of the other. A causal role that has not yet been identified does not cancel a standing that has already come to hold under the rules; nor does the holding of a standing prove that the corresponding effects have occurred. When analyzing the same arrangement, keep at least four items separate: whether the constitutive conditions are met, whether the parties understand it this way, whether it is executed and honored in practice, and whether it is normatively justified. A right may already be valid and not yet be honored; understanding a request is not the same as acknowledging that it has the standing to enter the decision.</p><p>A constitutive standing holds under the rules of the object&#39;s own domain and is supported by sources of law, documents, and records of acts by those entitled to perform them; the status of these materials is handled under §2.1.1. It is different from this framework&#39;s definition D, nor does it belong to the question of channel effects under G2. Pointing out that a standing is constituted by rules does not mean that all objects arise from convention, nor that the rules making the classification are thereby neutral or justified. Section 5.5.5 separates the de facto existence of an institution from its legal validity; the latter belongs to the constitutive question here. For the corresponding distinctions concerning forms of meaning and authorization, see §7.3.3 and §14.6.</p></div>',1)),n(a,{section:"2.4.3"}),e[3]||(e[3]=t('<div class="theory-source"><h2 id="section-2-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.5</span><span class="xk-num__gap"></span></span>Evidence Protocol <a class="header-anchor" href="#section-2-5" aria-label="Permalink to &quot;2.5 Evidence Protocol {#section-2-5}&quot;">​</a></h2><p>The evidence chain distinguishes sources, materials, observation records, evidence, counterexamples, judgments, and authorization to act. Each layer needs its own justification for conversion. Register the object, data-generation process, research design, measurement and selection, uncertainty, competing explanations, and limits of extrapolation according to the specific task. Formal root instances and foresight<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> must also register null models, thresholds, and evaluation under their own contracts. A material&#39;s having a source does not permit omitting the support relation between that material and the current claim.</p><p>Absence and silence are not negative evidence by default; inability to observe is not the same as nonexistence. Justified opacity must state its reason, minimum scope, duration, and trusted reviewer, with the strength of public conclusions reduced accordingly. If counterexamples or residuals are found after evidence has been frozen, the failure record should be retained, and the claim downgraded, suspended, or withdrawn under the contract. The object, subtype, threshold, or success criterion must not be rewritten after results appear.</p><h3 id="section-2-5-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.5.1</span><span class="xk-num__gap"></span></span>Measurement Objects and Data Generation <a class="header-anchor" href="#section-2-5-1" aria-label="Permalink to &quot;2.5.1 Measurement Objects and Data Generation {#section-2-5-1}&quot;">​</a></h3><p>Directly recorded quantities, composite indicators defined by construction, measurement of latent attributes, formative conditions, and predictive proxies carry different explanatory responsibilities. A test score can accurately reflect performance within the current set of questions while not yet representing long-term capability. Usage can fall while the required services are still insufficient. More diagnoses may also reflect easier access to testing. First state what is to be measured and how the materials are generated, then decide which errors and counterexamples are relevant to the current use.</p><p>Comparisons across groups or periods require comparability proportionate to the task. Estimating latent means generally requires explaining the unit and origin of the measurement scale. Person-specific threshold decisions must also address individual error and consequences. An identical scoring mapping does not establish identical psychological strategies. If the common anchors themselves drift, more samples may not distinguish genuine change from changes in the measurement scale. External anchoring should be sought, or sensitivity reported.</p><p>Changes in an indicator can result from genuine improvement, genuine adaptation to a narrow target, changes in the sample that enters or is reported, or falsification of records. These mechanisms can coexist and require separate investigation. Nor does the fact that two legitimate indicators answer different questions and point in opposite directions mean that one must be wrong, much less justify directly concluding that there has been manipulation.</p><h2 id="section-2-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.6</span><span class="xk-num__gap"></span></span>Analogy Protocol <a class="header-anchor" href="#section-2-6" aria-label="Permalink to &quot;2.6 Analogy Protocol {#section-2-6}&quot;">​</a></h2><p>Analogy is only a tool for generating questions. Every use must be explicitly marked as an analogy and specify the source domain, target domain, shared structure, key differences, nontransferable conditions, variable mapping, and discriminating tests. Similar words, similar diagrams, compelling narratives, or similar outcomes do not constitute evidence for a bridge across domains.</p><p>Analogy can help ask “which channel, boundary, or competing explanation should also be checked.” It cannot replace a G-instance, nor can it transfer causal relations, normative evaluations, or action plans directly from the source domain to the target domain. If contrary conditions have not been specified, the conclusion from the analogy remains a heuristic candidate.</p><h3 id="section-2-6-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.6.1</span><span class="xk-num__gap"></span></span>Analogy, Formal Instances, and Tested Comparisons <a class="header-anchor" href="#section-2-6-1" aria-label="Permalink to &quot;2.6.1 Analogy, Formal Instances, and Tested Comparisons {#section-2-6-1}&quot;">​</a></h3><p>A heuristic analogy, a formal instance satisfying explicit mathematical premises, and a target-domain relation tested against independent materials are three different states. For the first, state similarities and differences; for a formal instance, check variables and assumptions; for empirical transfer, test operations, formation processes, and alternative explanations in the target domain. A comparison supported by independent evidence can contribute to a specific argument. Its support comes from those materials and bridges, not from the word “like.”</p><p>Historical and archaeological comparisons must also distinguish the physical formation of traces, the functions of activities, and social relations. Similar tool marks do not automatically imply the same institutions of power; kinship does not automatically imply relations of rule; and accurate dates do not automatically yield an event&#39;s full meaning. Respect for different sources of knowledge does not require giving them equal weight on every question. Different materials may each supply content that cannot be substituted for the others.</p><h2 id="section-2-7" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.7</span><span class="xk-num__gap"></span></span>Source Protocol <a class="header-anchor" href="#section-2-7" aria-label="Permalink to &quot;2.7 Source Protocol {#section-2-7}&quot;">​</a></h2><p>Source records must specify the source domain, case type, time and region, scope of support, and limits of extrapolation item by item, and complete counterexample registration. Original materials, secondary interpretations, and this framework&#39;s inferences are kept in separate columns. Judgments in the text and their original locations are linked in both directions, so that readers can return from a judgment to the materials and see from the materials which limited claim they have been used to support.</p><p>Conceptual definitions, field mappings, and method descriptions specify only what is to be tested, how it is to be recorded, and where to stop drawing conclusions. They must not enter <code>empirical_evidence_records</code> as object facts or mechanism support. Internal terms, identifiers, examples, and the framework&#39;s own formulations cannot replace external materials. In other words, a method definition is not the same as empirical support.</p><p>Empirical support must come from independently registered instance materials and include the object and scale, time window, research design, N0, outcomes, uncertainty, review or reproduction, and evidential level. Without corresponding external instance materials, specific empirical assertions within the G question families cannot acquire formal empirical support. C is used separately for outcome registration, mechanism conditions, and normative bridging; real-world mechanism judgments under CM still need the corresponding instance evidence. A question catalog, outcome contracts, and the framework&#39;s own descriptions cannot replace the missing materials.</p><h3 id="section-2-7-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.7.1</span><span class="xk-num__gap"></span></span>Relations between Sources and the Scope of Actual Use <a class="header-anchor" href="#section-2-7-1" aria-label="Permalink to &quot;2.7.1 Relations between Sources and the Scope of Actual Use {#section-2-7-1}&quot;">​</a></h3><p>Reading a table of contents, an abstract, relevant chapters, or the full text should be recorded separately. Finding a link, completing a download, and understanding an argument are also different actions. Relations between sources should be retained for different analyses of the same data, a preprint and its published version, and an original report and an institution&#39;s account of it. Citation counts must not be added up as independent reproductions. When a version changes outcomes, samples, or reporting definitions, first explain the changes, then compare conclusions.</p><p>A theory&#39;s historical adoption, mere mention, explicit restriction or rejection, compatibility with the current text, and a new connection now proposed by the analyst are distinct matters. Failure to find a record of adoption is not the same as its never having been considered; transcribing a catalog is not the same as checking the original document. Failure to obtain a document within one research window does not mean that other researchers or the project as a whole lack it.</p><p>The generation, preservation, destruction, opening, and retrieval of archives, as well as narrative choices, can each cause absence. Absence has the corresponding force as counterevidence only when it is clear that a certain kind of event should have left records that could be found. Inaccurate dates in oral accounts still need correction, while the way the account is told may also be important material for understanding memory and experience. Neither cancels the other.</p><h3 id="section-2-7-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.7.2</span><span class="xk-num__gap"></span></span>Evidence Independence and the Propagation of Defects <a class="header-anchor" href="#section-2-7-2" aria-label="Permalink to &quot;2.7.2 Evidence Independence and the Propagation of Defects {#section-2-7-2}&quot;">​</a></h3><p>Independence must be judged relative to the claim being supported. Adding later outcomes to the same random assignment can add temporal and outcome information. Testing the same data with another algorithm can uncover implementation or interpretation problems. Neither increases the number of independent randomizations or original cohorts. Conversely, studies on the same subject but with different underlying samples must not be merged merely because their names are similar. Records should specify shared data, common measurements, version inheritance, and genuinely new observations, rather than turn a file count into an evidence score.</p><p>Traceable dependencies should be retained between source values, transcriptions, model inputs, derived statistics, and judgments in the text. When a local discrepancy is found, first distinguish conflict concerning the same object, legitimate differences between different objects, and apparent inconsistency caused by display precision. Then suspend the precise conclusions that actually depend on that discrepancy. Reconciliation of the component sum with the total does not by itself validate every component, nor does a source anomaly reveal the cause of a discrepancy on its own. Other judgments with independent support should continue to be used within their actual scope.</p><h2 id="section-2-8" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.8</span><span class="xk-num__gap"></span></span>Core Terminology Locks <a class="header-anchor" href="#section-2-8" aria-label="Permalink to &quot;2.8 Core Terminology Locks {#section-2-8}&quot;">​</a></h2><p>Once the following terms enter a judgment, they must satisfy their specified contracts. Their broad everyday meanings must not be substituted for those contracts.</p><p>Cost. First declare the quantity&#39;s type, unit, time window, accounting boundary, and cost-bearing position. Shifting may be traced only for quantities of the same type, or quantities of different types with an explicit conversion and accounting mapping. “Resources are occupied” is not the same as the existence of a unified cost across domains, nor does it establish any conservation principle.</p><p>Externality. First establish a cross-boundary causal channel and the positions across which its effects are distributed, then an institutional or accounting rule defining what is excluded from decision accounting. Without the latter, the effect can only be called a cross-boundary spillover, impact, or accounting gap. “Externality” must not be used to assign responsibility in advance.</p><p>The exclusion rule here may come from an explicit economic model or actual institutional and accounting arrangements. It does not require an advance determination of legal liability. The current inability to identify who bears legal liability does not prevent recording cross-boundary harm for which evidence already exists. C7 addresses cross-boundary spillovers and the positions across which they are distributed under its specified conditions. Where changes of scale are actually involved, D3/E5 must be checked separately; claims of closure failure or conversion of objects or interventions also require testing the corresponding G4. It does not cover all economic externalities or propagation in general.</p><p>Repair. The target identity criterion K* or functional criterion F* must be disclosed before results. Repair is not the same as recovery of a historical state, nor is it the same as improvement in value. Whether the target is justified, who decides it, and who may carry it out require separate review under N and O.</p><p>Selection and choice. First distinguish modes of systemic selection, choices by acting subjects, and governance choices. The systemic process of variation–differential retention–reproduction does not possess intent as a matter of course. A subject&#39;s decision is not the same as environmental selection. Governance choice additionally requires normative premises and authorization.</p><p>Responsibility and authorization. Uptake carriers, bearers of costs of the same type, beneficiaries, rights to stop, and responsible parties are registered separately. Actual execution, the greatest capability, being most affected, being most visible, or possessing knowledge cannot by themselves establish responsibility. Nor can an expansion of observational scope or confidence in explanation expand authority to act.</p><p>Bearing obligations requires a separate account of the relations among commitments, roles, causal contributions, benefits, capabilities, and applicable norms. These reasons may act together; no one of them can automatically settle the whole matter. Disclosing bounded obligations and their boundaries does not make anyone a person required to take up obligations without limit, unilaterally, and without the possibility of exit.</p><h2 id="section-2-9" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.9</span><span class="xk-num__gap"></span></span>Missing Fields and Visibility States, Downgrading, Suspension, and Exit <a class="header-anchor" href="#section-2-9" aria-label="Permalink to &quot;2.9 Missing Fields and Visibility States, Downgrading, Suspension, and Exit {#section-2-9}&quot;">​</a></h2><p>Every contract field must fall within an explicit state, rather than be filled with vague wording.</p><p>Unknown: knowable in principle, but current evidence is insufficient.</p><p>Not applicable: the field has no valid counterpart in the current object contract; a reason must be stated.</p><p>Unobservable: materials cannot currently be obtained because of limits in measurement capability, the window, or the channel; this must not be rewritten as nonexistence.</p><p>Withheld for protection: materials exist, but disclosure would violate privacy, security, or other explicit protections. The basis for protection, minimum scope of non-disclosure, duration, and a trusted review path must be recorded.</p><p>When key variables are unknown, conditions under which the object is not applicable remain unaddressed, core channels are unobservable, or non-disclosure for protection cannot undergo trusted review, conclusions are downgraded successively to candidate hypotheses, lists of questions, or description only. When authorization to act is unclear, potential harm is irreversible, appeals and stopping are inaccessible, or the limits of professional capability would be exceeded, real-world action should be suspended and referred to an appropriate procedure. Downgrading is not analytical failure. It keeps the evidential ceiling, boundaries of power, and what is still unknown visible. Each downgrade is registered proposition by proposition with its dependencies and the effects of what is missing. Other judgments with independent support are not downgraded along with it; failure of a global source, common premise, or object boundary blocks all related outputs.</p><h2 id="section-2-10" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.10</span><span class="xk-num__gap"></span></span>Methodological Boundaries for Multi-Circle Objects <a class="header-anchor" href="#section-2-10" aria-label="Permalink to &quot;2.10 Methodological Boundaries for Multi-Circle Objects {#section-2-10}&quot;">​</a></h2><p>Circles<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> are first of all candidate groupings, not natural entities established by naming. Families, organizations, platform groups, occupational communities, or cultural categories should specify boundaries, members, roles, channels, time windows, and identity criteria. Documents, relationship records, or exposure records can support the relevant facts about objects. A claim that the grouping brings explanatory or foresight gains must then be compared against suitable simple baselines, such as no grouping or a single circle. Formal G1 support does not replace other grounds for the object&#39;s existence. Parallelism, nesting, and overlap are judged along the declared dimensions. Potential bridging, actual transmission, and effects of transmission require separate evidence. Competition specifies constraints on the available set; temporariness specifies a time limit or evidence concerning duration. Both can be combined with other relations.</p><p>Multi-circle analysis must not turn every background factor into an entity. Before a circle is added, the necessary question it answers, the distinction that would be lost if it were removed, and the measurement and privacy costs should be stated. If it is used for explanation or propagation, the relevant channels and competing explanations must also be specified. Where its current purpose cannot be stated, retain it as an environmental condition or candidate variable. When a complex model lacks stable comparative support, reduce the relevant gain claims and give priority to an adequate simple model. Retaining an object to describe supported responsibilities, differences in membership, or authority over matters does not first require proving that it increases predictive accuracy.</p><h2 id="section-2-11" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.11</span><span class="xk-num__gap"></span></span>Methodological Boundaries for Personality and Actor States <a class="header-anchor" href="#section-2-11" aria-label="Permalink to &quot;2.11 Methodological Boundaries for Personality and Actor States {#section-2-11}&quot;">​</a></h2><p>Personality enters only as a slow-variable hypothesis with an evidential level, not as an ontological definition of a person. A single behavior, self-report, report by someone else, scale score, or model-generated cluster cannot by itself establish a stable personality. Analysis must also retain competing explanations such as role activation, material constraints, immediate emotions, strategies, cultural norms, observer position, and measurement bias.</p><p>Actor variables are divided by timescale into slow, intermediate, and fast bands. Each is tied to an observation window, source, counterevidence, circle conditions, privacy, and permitted uses. The framework does not perform clinical or psychiatric diagnosis, nor does it record silence, refusal to disclose, or unobservability as pathological evidence. A model may propose candidate variables and minimal tests; it must not automatically fill in real-world values.</p><h2 id="section-2-12" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.12</span><span class="xk-num__gap"></span></span>Methodological Boundaries for Foresight and Projection <a class="header-anchor" href="#section-2-12" aria-label="Permalink to &quot;2.12 Methodological Boundaries for Foresight and Projection {#section-2-12}&quot;">​</a></h2><p>Path projection may use observations, reports, plans, hypothetical events, and simulated events, but must retain the event type. A report&#39;s content is not automatically true; a plan is not the same as execution; hypothetical and simulated events are not written back as real-world facts. Each run freezes the joint snapshot, evidence cutoff, mechanisms, parameter ranges, clocks, propagation rules, and stopping conditions. Information obtained after the results may enter only a new version.</p><p>Conditional foresight must register, before results, the target, horizon, scope of objects and circles, input cutoff, simple baseline, paths, form of expression, calibration metrics, early signals, contrary signals, suspension, retirement, and outcome write-back. Unregistered post hoc explanations do not count as successful predictions. Changing the target, extending the horizon, narrowing the population, or merging paths all require a new record. For reopening on stated grounds, see §2.14.</p><h2 id="section-2-13" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.13</span><span class="xk-num__gap"></span></span>Limits on Autonomous Variable Refinement <a class="header-anchor" href="#section-2-13" aria-label="Permalink to &quot;2.13 Limits on Autonomous Variable Refinement {#section-2-13}&quot;">​</a></h2><p>“Autonomous variable refinement” permits only three actions: proposing multiple competing candidates from residuals; stating which channels a candidate might act through and what observable implications it might produce; and designing a minimal test with acceptable risk. Candidates move in sequence through the states proposed, under test, supported candidate, rejected, or retired. They must not jump directly from a model suggestion to an observed fact, a personality conclusion, a supported circle, or a causal mechanism.</p><p>If a candidate concerns privacy, health, safety, legal standing, or a position with little power, the necessity of obtaining the information, its use, and its harms should be reviewed first. When the value of the information is insufficient to outweigh the risk, retaining the unknown status is more appropriate than actively filling in the information.</p><h2 id="section-2-14" tabindex="-1"><span class="xk-num"><span class="xk-num__n">2.14</span><span class="xk-num__gap"></span></span>Freezing and Reopening a Question <a class="header-anchor" href="#section-2-14" aria-label="Permalink to &quot;2.14 Freezing and Reopening a Question {#section-2-14}&quot;">​</a></h2><p>An analysis freezes the boundaries of the object and its membership, the definitions of the target and of loss, the admissible operations, the horizon, and the resource and permission constraints treated as given, so that its judgments can be checked. Freezing does not give the person who posed the question a monopoly over it. Two kinds of reason can require reopening: the current representation is insufficient to answer the original question, so that distinctions must be added or the task narrowed; or someone contends that one of the items above was itself set improperly—for example, the interests the target represents, who counts as a member, what counts as a loss, or which constraints are treated as given. Challenges of the latter kind may come from affected and excluded parties, and also from the analyst.</p><p>Whether or not a request to reopen is accepted, register who raised it, the reasons, and the grounds on which it was handled; when a question is reopened, retain the original question and its results. A failed original prediction is not recorded as a success because the question has changed, and an unfinished original task is not treated as finished because a new task has been completed (§12.7, §4.19). The new question is established separately, with a statement of why it holds, whether it replaces, runs parallel to, or refines the original question, and which of the existing evidence still applies under the new object and target. The analyst may answer both questions side by side, stating the grounds for each; for indicators, eligibility, agendas, or resource allocation internal to an institution, whether to change them is decided by procedures with the corresponding authority, and objections from affected parties are handled under §14.5.</p><p>The reason for reopening must not be merely that the result is unfavorable. A result can expose an insufficient representation, and it can also expose losses, positions, or members that were not previously counted; these are all reasons. Changing the target only because the result is unfavorable amounts to selecting favorable results after the fact (§2.12, §4.1). Reopening does not rewrite the original question; it establishes a separate question under the changed given items. The formal conclusions of §4.19 hold only for the original state, target, action, and horizon; for the new question, the representation and evidence must be checked again.</p></div>',1)),n(a,{section:"2.14"}),e[4]||(e[4]=t('<div class="theory-source"></div><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Translator&#39;s note: A contract here is an analytical agreement registered and frozen before results, close to pre-registration; it is not a legal instrument. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>Translator&#39;s note: Diagnosis within this framework is nonclinical. Section 2.11 expressly excludes clinical and psychiatric diagnosis; references to diagnoses in measurement examples do not change that limit. <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>Translator&#39;s note: Protocol translates 契约 and denotes a methodological check that a judgment must pass. It is distinct from contract, which translates 合同. <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p>Translator&#39;s note: Foresight here requires registered targets, horizons, and baselines, together with calibration. A single such judgment is called a forecast. <a href="#fnref4" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p>Translator&#39;s note: Circles may be parallel, nested, overlapping, or bridged; the term does not imply a hierarchy. <a href="#fnref5" class="footnote-backref">↩︎</a></p></li></ol></section>',3))])}const b=i(c,[["render",l]]);export{g as __pageData,b as default};
